import sprite
ROOT = '/home/claude/NyanCat6767/lib/data'
# ---------- sprite_data.dart
fa, fb = sprite.build_frame(0), sprite.build_frame(1)
acc = sprite.acc_cells()
ROLE = {'a': 0, 'b': 1, 'c': 2, 'k': 3}
out = ["// GENERATED by tools/gen_dart_data.py - original pixel-art sprite for the cat.", "// Roles: k outline, c crust, f frosting, s sprinkle, z/y frosting accents, g fur, p cheek/nose, e eye, w eye highlight.", ""]
out.append('const int kSpriteW = %d;' % sprite.W); out.append('const int kSpriteH = %d;' % sprite.H)
out.append('const int kSpriteOx = %d;' % sprite.OX); out.append('const int kSpriteOy = %d;' % sprite.OY); out.append('')
for nm, fr in (('kFrameA', fa), ('kFrameB', fb)):
    out.append('const List<String> %s = <String>[' % nm)
    for r in fr: out.append("  '%s'," % r)
    out.append('];'); out.append('')
out.append('/// Accessory pixels as flat triples: x, y, role(0=a,1=b,2=c,3=outline) in sprite-grid coordinates.')
out.append('const Map<String, List<int>> kAccessoryPixels = <String, List<int>>{')
for name, items in acc.items():
    flat = []
    for (x, y, ch) in items: flat += [x + sprite.OX, y + sprite.OY, ROLE[ch]]
    out.append("  '%s': <int>[%s]," % (name, ','.join(str(v) for v in flat)))
out.append('};'); out.append('')
open(ROOT + '/sprite_data.dart', 'w').write('\n'.join(out))

