assert len(SK) == 32 and len({s['id'] for s in SK}) == 32
def hx(h): return '0xFF' + h.upper()
def lst(v): return '<int>[' + ', '.join(hx(c) for c in v) + ']'
lines = []
for s in SK:
    z = s['z'] or s['frost']; y = s['y'] or s['frost']
    lines.append("  SkinDef(id: '%s', nameEn: '%s', nameBg: '%s', rarity: Rarity.%s, price: %d,\n"
                 "      outline: %s, crust: %s, frost: %s, sprinkle: %s, accentZ: %s, accentY: %s, fur: %s, cheek: %s, eye: %s, eyeHi: %s,\n"
                 "      trail: %s, acc: Accessory.%s, accA: %s, accB: %s, accC: %s,\n"
                 "      fx: Fx.%s, fxColors: %s, aura: %s, hue: %s, hueSpeed: %d, ghost: %s)," % (
        s['id'], s['en'], s['bg'], s['rar'], s['price'], hx(s['outline']), hx(s['crust']), hx(s['frost']), hx(s['sprinkle']), hx(z), hx(y), hx(s['fur']), hx(s['cheek']), hx(s['eye']), hx(s['eyeHi']),
        lst(s['trail']), s['acc'], hx(s['a']), hx(s['b']), hx(s['c']), s['fx'], lst(s['fxc']), hx(s['aura']), 'true' if s['hue'] else 'false', s['hs'], 'true' if s['ghost'] else 'false'))
open('skins_list.txt', 'w').write('\n'.join(lines))
